fn test_pep_gates_the_floor_principal_deny_by_default() {
	prog := "[?lib 'cx-stdlib/session' :as s]
[?lib 'cx-stdlib/authz' :as authz]
[?let [= \$pair [\$s:attach-guest [request scheme=\"https\"] {anonymous-floor: \"web-public\" tenant: \"shop\"}]]
