// ── source: vcx/tests/stdlib_supervise_test.v ──
// stdlib_supervise_test.v — the timing-sensitive supervise arms that the
// conformance corpus cannot fixture (spec/03-approved/std-lib/supervise.md
// §10; RULED: SUP-1, rider SUP-1f — ledger/rulings_2026_08_20_supervise.md).
//
// The .cxd corpus (conformance/stdlib/supervise.cxd) pins every
// deterministic arm. What lives HERE is the no-hang guarantee against a
// WEDGED child — one that swallows the cancellation err and keeps
// computing without ever crossing another cancellation point. On the
// reference substrate `[?cancel]` stamps the WORKER_CANCELLED terminal
// at request time (state_locks.v cancel-wins arbitration, §10.5.4), so
// the supervisor's shutdown-bounded wait resolves promptly and
// `[child-abandoned]` is unreachable — a .cxd fixture cannot observe a
// shutdown-window expiry. This lane pins the two live guarantees:
//
//   1. NO-HANG: `stop` of a supervisor whose child is mid-way through a
//      cancellation-point-free compute returns promptly (bounded by the
//      child's shutdown= plus loop slack), never joins the compute.
//   2. TERMINAL HONESTY: the stopped supervisor's status reports the
//      child `stopped` (the platform's requested-outcome terminal), and
//      the wedged body's late note (posted after its compute finally
//      ends, if its send is not itself refused at the cancellation
//      point) never resurrects the child — the stale-incarnation guard
//      drops it.

// A child that swallows the cancellation err raised at its blocking
// receive and then busy-computes ~1M pure recursion steps (seconds of
// CPU, zero cancellation points) — the honest "wedged" shape §4.4
// names: cancellation is cooperative and this body stops cooperating.
const wedged_prog = "[?lib 'cx-stdlib/supervise' :as sup]
[?def busy scope=public pure [returns int] (\$n::int)
  [?if [< \$n 1] [then 0] [else [busy [- \$n 1]]]]]
[?let [= \$never [?channel name=\"vlane-never\" buffer=1]]
[= \$s [\$sup:start [policy strategy=:one-for-one max-restarts=3]
        ([child name=\"w\" shutdown=200ms
           [fn [?fn () [?fallback [?receive from=\$never]
                         [recover-with [busy 1000000]]]]]])]]
[= \$ev [\$sup:events \$s]]
[= \$e0 [?receive from=\$ev max=1 deadline=8000]]
[= \$_stp [\$sup:stop \$s]]
[= \$st [\$sup:status \$s]]
\$st]"

fn test_wedged_child_stop_no_hang_and_terminal_honesty() {
	sw := time.new_stopwatch()
	out := code.eval_code('', wedged_prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	elapsed_ms := sw.elapsed().milliseconds()
	// Terminal honesty: the child reports stopped (the request-stamped
	// terminal), never a hang, never a phantom 'running'.
	assert out.contains('[child name=w state=stopped'), 'expected the wedged child reported stopped, got: ${out}'
	assert out.contains('restarts-in-window=0'), 'a supervisor-initiated stop must never count against intensity, got: ${out}'
	// No-hang: the whole program — start, stop (bounded by shutdown=200ms
	// + loop slack), status — must complete WITHOUT joining the wedged
	// compute (~seconds of CPU). EV-WORKER-EXIT drains the compute at
	// program end, which eval_code includes, so the bound here is the
	// compute duration plus slack: the assertion is that stop() itself
	// did not ALSO serialize a second compute-length wait. 60s is the
	// generous CI ceiling; the typical run is a few seconds.
	assert elapsed_ms < 60_000, 'wedged-child stop took ${elapsed_ms}ms — the supervisor hung on a wedged child'
}

// The same wedged shape under stop-child: the verb returns true (the
// child was present and is removed) promptly — the no-hang guarantee at
// the per-child verb.
const wedged_stop_child_prog = "[?lib 'cx-stdlib/supervise' :as sup]
[?def busy2 scope=public pure [returns int] (\$n::int)
  [?if [< \$n 1] [then 0] [else [busy2 [- \$n 1]]]]]
[?let [= \$never [?channel name=\"vlane-never2\" buffer=1]]
[= \$ok [?channel name=\"vlane-ok2\" buffer=1]]
[= \$s [\$sup:start [policy strategy=:one-for-one max-restarts=3]
        ([child name=\"w\" shutdown=200ms
           [fn [?fn () [?fallback [?receive from=\$never]
                         [recover-with [busy2 1000000]]]]]],
         [child name=\"keep\" [fn [?fn () [?receive from=\$ok]]]])]]
[= \$ev [\$sup:events \$s]]
[= \$e0 [?receive from=\$ev max=2 deadline=8000]]
[= \$r [\$sup:stop-child \$s \"w\"]]
[= \$st [\$sup:status \$s]]
[= \$_stp [\$sup:stop \$s]]
(\$r, \$st)]"

fn test_wedged_child_stop_child_prompt() {
	out := code.eval_code('', wedged_stop_child_prog, 'text') or {
		assert false, 'eval failed: ${err}'
		return
	}
	assert out.contains('true'), 'stop-child of a present (wedged) child must return true, got: ${out}'
	assert out.contains('[child name=keep state=running'), 'the sibling must be untouched by a wedged stop-child, got: ${out}'
	assert !out.contains('name=w state='), 'stop-child must REMOVE the child from status, got: ${out}'
}

// ── #1024: the [authz-store] REGISTRY tier reads under the #997 lock ─────────
//
// #997 serialized this tier's WRITES and left its reads bare, because a read
// bracket cannot simply be wrapped around a verb that then writes: a pthread
// rwlock does not upgrade, so it self-deadlocks. The 19 verb entry points
// reaching authz_store_from_arg were classified by hand (the table lives on
// authz_grants_rlock in stdlib_authz.v) into basis-untouched (4), basis
// read-only (12) and basis read-then-write (3); the read-only set is bracketed
// and the read-then-write set is restructured read-then-decide-then-write.
//
// WHAT THIS PIN IS. A [?worker] hammering the PEP while the main thread dials
// the same store — the registry-tier analogue of #997's deployment pair, in the
// shape a CX program actually reaches these verbs from. `ops-1` holds a STANDING
// grant seated before the race starts, so after that point every check MUST
// permit: a torn or stale basis read is a DENY for an actor who holds the grant,
// which is the authority defect, not a performance blemish. The noise dials go to
// a different actor, so the reader's answer never depends on them — only its walk
// does.
//
// Both halves are asserted:
//   * DENIES == 0 — and this is a SUM, not an iteration count. `[$count $c/reason]`
//     is 1 on a [deny …] (it carries [reason …]) and 0 on a [permit …], so
//     [$sum …] over the reader's yields is exactly the number of denials. (A
//     [$count [?for …]] here would have counted iterations and asserted nothing —
//     it would be green against any decision at all.)
//   * NOISEINBASIS == the dials issued (no append lost on the way in),
// plus a clean exit (no SIGSEGV inside the evaluator).
//
// HONESTLY, ON RED-PROOF. Removing the read bracket around authz_decide does NOT
// fail this pin: measured 8 of 8 clean at this size. That is the same finding
// #997 recorded for its own deployment half, and the mechanism is now understood:
// `delegations` is a GROW-ONLY array of heap POINTERS under a tracing GC, so a
// reader that captured a stale buffer sees an older PREFIX of valid records — a
// benign stale read, not a torn one, and `ops-1`'s grant is in every prefix. The
// read bracket's warrant is therefore the part the rate does not touch: an
// unbracketed walk of a concurrently-pushed array is undefined behavior whatever
// the observed rate, and the multi-walk verbs (check walks twice, effective twice,
// meters folds then emits) can otherwise answer from two different bases.
//
// What IS red-proven, deterministically and single-threaded, is the DEADLOCK the
// classification exists to avoid — see
// test_authz_registry_read_bracket_cannot_span_a_write below.
fn test_authz_registry_reads_survive_a_worker_hammering_a_live_dial() {
	// 3000/3000 is #997's size: where that probe's pre-fix outcome stopped being a
	// coin flip. One round is ~1.1s at 133% CPU, i.e. the overlap is real and the
	// whole pin stays far inside the 25s bound the concurrency probes are held to.
	per := 3000
	prog := "[?lib 'cx-stdlib/authz']
[?let [= \$az [\$authz:store {tenant: 'acme'}]]
      [= \$seed [\$authz:delegate \$az
                  [delegation d-standing [tenant acme] [from [principal dana]] [to [agent ops-1]]
                    [capabilities [refund]] [over '/orders'] [assurance :t1] [signature s]]]]
      [= \$r1 [?worker name=r1 [\$sum [?for [in \$i [\$range 1 ${per}]]
                [yield [?let [= \$c [\$authz:check \$az [authz-request [actor [agent ops-1]]
                                      [capability refund] [slice '/orders/9'] [tenant acme]]]]
                        [\$count \$c/reason]]]]]]]
      [= \$w [\$count [?for [in \$i [\$range 1 ${per}]]
                [yield [?let [= \$d [\$authz:delegate \$az
                                      [delegation [?str 'd-n{\$i}'] [tenant acme]
                                        [from [principal dana]] [to [agent ops-noise]]
                                        [capabilities [refund]] [over '/orders']
                                        [assurance :t1] [signature s]]]]
                        1]]]]]
      [= \$denies [?wait-for worker=\$r1]]
      [= \$g [\$authz:grants-of \$az [agent ops-noise]]]
  [out [?str 'DIALED={\$w} DENIES={\$denies} NOISEINBASIS={[\$count \$g]}']]]
"
	tmp := os.join_path(os.temp_dir(), 'cx-authz-1024-race-${os.getpid()}.cx')
	os.write_file(tmp, prog) or { panic('write: ${err}') }
	defer {
		os.rm(tmp) or {}
	}
	// Four rounds — the interleaving is the variable, so one clean round is not
	// evidence.
	for round in 1 .. 5 {
		r := os.execute('${testenv.cx_bin()} --allow-read ${tmp}')
		assert r.exit_code == 0, 'round ${round}: a [?worker] deciding while the main thread dialed killed the process (rc=${r.exit_code}) — the registry tier walked a basis another thread was growing (#1024):\n${r.output}'
		want := 'DIALED=${per} DENIES=0 NOISEINBASIS=${per}'
		assert r.output.contains(want), 'round ${round}: expected `${want}`, got: ${r.output.trim_space()}\n(DENIES > 0 = the PEP DENIED an actor holding a standing grant, which is the #997/#1024 authority defect; NOISEINBASIS short = a dial was lost on the way in)'
	}
}

// The DEADLOCK half, and the red instrument for the whole classification. The
// naive fix #1024 warns about — wrap the verb in a read bracket — is not merely
// suboptimal on the three read-then-write verbs: it hangs, on the FIRST call,
// single-threaded, because authz_grants_append takes the WRITE lock while the
// read lock is still held and a pthread rwlock does not upgrade.
//
// Red-proven by construction: moving authz_delegate_impl's authz_grants_runlock()
// to below its authz_grants_append() makes the store+delegate program below hang
// forever (measured: killed at a 20s bound, having produced nothing). That result
// also rules out the OTHER way this whole change could be vacuous — the #303 /
// #997 failure mode where a value-typed zeroed rwmutex is a silently non-locking
// pthread rwlock. A lock that did not lock would have let the naive shape run
// clean. This test is the green side: every verb class in one program, and the
// assertion is that it COMPLETES.
fn test_authz_registry_read_bracket_cannot_span_a_write() {
	// One program touching all three classes: read-then-write (delegate, revoke
	// with cascade, grant-guardian), basis read-only (check, find, grants-of,
	// effective, trace, resolve-cap), and basis-untouched (verify-tier, close).
	prog := "[?lib 'cx-stdlib/authz']
[?let [= \$az [\$authz:store {tenant: 'acme'}]]
      [= \$d1 [\$authz:delegate \$az
                [delegation d-root [tenant acme] [from [principal dana]] [to [agent ops-1]]
                  [capabilities [refund]] [over '/orders'] [assurance :t1] [signature s]]]]
      [= \$d2 [\$authz:delegate \$az
                [delegation d-kid [tenant acme] [attenuates 'd-root'] [from [agent ops-1]]
                  [to [agent ops-2]] [capabilities [refund]] [over '/orders']
                  [assurance :t1] [signature s]]]]
      [= \$c1 [\$authz:check \$az [authz-request [actor [agent ops-1]] [capability refund] [slice '/orders/9'] [tenant acme]]]]
      [= \$au [\$authz:authorize \$az [authz-request [actor [agent ops-2]] [capability refund] [slice '/orders/9'] [tenant acme]]]]
      [= \$dr [\$authz:dry-run \$az [authz-request [actor [agent ops-1]] [capability refund] [slice '/orders/9'] [tenant acme]]]]
      [= \$f [\$authz:find \$az 'd-root']]
      [= \$g [\$authz:grants-of \$az [agent ops-1]]]
      [= \$ef [\$authz:effective \$az [agent ops-1]]]
      [= \$tr [\$authz:trace \$az [authz-request [actor [agent ops-1]] [capability refund] [slice '/orders/9'] [tenant acme]]]]
      [= \$vt [\$authz:verify-tier \$az
                [delegation d-root [tenant acme] [from [principal dana]] [to [agent ops-1]]
                  [capabilities [refund]] [over '/orders'] [assurance :t1] [signature s]]]]
      [= \$rv [\$authz:revoke \$az 'd-root' {cascade: true}]]
      [= \$after [\$authz:check \$az [authz-request [actor [agent ops-2]] [capability refund] [slice '/orders/9'] [tenant acme]]]]
      [= \$cl [\$authz:close \$az]]
  [out [seq [root \$c1] [kid \$au] [dry \$dr] [found \$f] [granted [?splice \$g]] [envelope \$ef]
            [traced [?splice \$tr]] [tier \$vt] [revoked \$rv] [cascaded \$after]]]]
"
	tmp := os.join_path(os.temp_dir(), 'cx-authz-1024-classes-${os.getpid()}.cx')
	os.write_file(tmp, prog) or { panic('write: ${err}') }
	defer {
		os.rm(tmp) or {}
	}
	sw := time.new_stopwatch()
	r := os.execute('${testenv.cx_bin()} --allow-read ${tmp}')
	elapsed_ms := sw.elapsed().milliseconds()
	assert r.exit_code == 0, 'the all-verb-classes program did not complete (rc=${r.exit_code}) — a read bracket that spans a write self-deadlocks (#1024):\n${r.output}'
	// A deadlocked run cannot reach here at all, so the timing is a guard against
	// a lock that merely CONTENDS pathologically rather than hanging outright.
	assert elapsed_ms < 30_000, 'the all-verb-classes program took ${elapsed_ms}ms — the registry brackets are contending, not just serializing (#1024)'
	out := r.output
	// The decisions are asserted on their RENDERED form, not through a `/permit`
	// path: the decision value IS the [permit …] / [deny …] element, so a path step
	// naming it selects nothing and `[$count $c/permit]` is 0 for a permit — an
	// assertion that would have passed against a deny.
	assert out.contains('[root [permit rooted-principal=dana'), 'the standing grant must permit, rooted at the principal — got: ${out.trim_space()}'
	assert out.contains('[kid [permit rooted-principal=ops-1'), 'the attenuating child must permit — got: ${out.trim_space()}'
	assert out.contains("[via 'd-root' 'd-kid']"), 'the child\'s permit must carry the FULL chain to the principal — a bracket that dropped a chain step would still permit, so the chain itself is the assertion (#997\'s instrument): ${out.trim_space()}'
	assert out.contains('[dry [permit'), 'dry-run shares check\'s entry point and must agree with it — got: ${out.trim_space()}'
	assert out.contains('[found [delegation id=d-root'), 'find must return the seated delegation — got: ${out.trim_space()}'
	assert out.contains('[granted [delegation id=d-root'), 'grants-of must see the actor\'s grant — got: ${out.trim_space()}'
	assert out.contains('[envelope actor=ops-1 [capabilities [refund]]]'), 'effective must intersect to the held capability — got: ${out.trim_space()}'
	assert out.contains('[traced [step'), 'trace must report the chain step it walked — got: ${out.trim_space()}'
	assert out.contains('[tier [verified'), 'verify-tier resolves the handle and then never touches the basis — got: ${out.trim_space()}'
	assert out.contains('[revoked [delegation id=d-root mode=delegated state=revoked'), 'revoke must report the row as revoked — the flip now goes through authz_grants_mark_revoked\'s write lock, not a bare in-place assignment: ${out.trim_space()}'
	// The cascade is the sharp one: it journals per link and RECURSES, so it can
	// hold no lock across its body — it collects each LEVEL's children under one
	// read bracket and applies them after the release. If that restructure had lost
	// the recursion, the child would still PERMIT here.
	assert out.contains('[cascaded [deny actor=ops-2'), 'revoke cascade=true must reach the attenuating child — the per-level bracketed collect must still recurse: ${out.trim_space()}'
}
